// READ ONLY. GET urls only.
const q = ($input.first().json.query) || {};
if (q.s !== 'eefe89214cd29e3830c5b50559f4ada2') { throw new Error('forbidden'); }
const BASE = 'https://api.lokalise.com/api2';
const mode = q.mode || 'projects';
if (mode === 'projects') {
  return [{ json: { mode: 'projects', pid: '', url: BASE + '/projects?limit=100&page=1' } }];
}
const pids = String(q.pids || '').split(',').map(s => s.trim()).filter(Boolean);
if (!pids.length) { throw new Error('pids required'); }
let f = '&filter_archived=exclude';
if (q.tags) f += '&filter_tags=' + encodeURIComponent(q.tags);
if (q.keys) f += '&filter_keys=' + encodeURIComponent(q.keys);
if (q.ids) f += '&filter_key_ids=' + encodeURIComponent(q.ids);
if (q.langs) f += '&filter_translation_lang_ids=' + encodeURIComponent(q.langs);
const names = mode === 'names';
return pids.map(pid => ({ json: { mode: names ? 'names' : 'keys', pid, f, url: BASE + '/projects/' + pid + '/keys?limit=1&page=1' + f } }));

const cfg = $('Config').all();
const out = [];
$input.all().forEach((it, i) => {
  const c = cfg[i].json;
  if (c.mode === 'projects') { out.push({ json: { mode: 'projects', pid: '', total: null, url: c.url } }); return; }
  const h = it.json.headers || {};
  const total = Number(h['x-pagination-total-count'] || 0);
  const pages = Math.max(1, Math.ceil(total / 500));
  const tr = c.mode === 'names' ? 'include_translations=0' : 'include_translations=1&include_comments=1&include_screenshots=1';
  for (let p = 1; p <= pages; p++) {
    out.push({ json: { mode: c.mode, pid: c.pid, total, url: 'https://api.lokalise.com/api2/projects/' + c.pid + '/keys?' + tr + '&disable_references=1&limit=500&page=' + p + c.f } });
  }
});
return out;

const meta = $('Expand').all();
const PSEUDO = new Set(['pst','ps','cus','pt_old']);
const res = { mode: 'keys', projects: {}, errors: [] };
$input.all().forEach((it, i) => {
  const m = meta[i].json;
  const body = it.json.body || {};
  if (m.mode === 'projects') {
    res.mode = 'projects';
    if (!Array.isArray(body.projects)) { res.errors.push(JSON.stringify(body).slice(0,300)); return; }
    res.list = body.projects.map(p => ({ id: p.project_id, name: p.name, keys: (p.statistics||{}).keys_total }));
    return;
  }
  const P = res.projects[m.pid] || (res.projects[m.pid] = { server_total: m.total, keys_seen: 0, archived: 0, rows: [] });
  if (!Array.isArray(body.keys)) { res.errors.push({ pid: m.pid, url: m.url, body: JSON.stringify(body).slice(0,300) }); return; }
  for (const key of body.keys) {
    P.keys_seen++;
    if (key.is_archived) { P.archived++; continue; }
    const name = typeof key.key_name === 'object' ? (key.key_name.web || key.key_name.other || key.key_name.ios || key.key_name.android || '') : key.key_name;
    if (m.mode === 'names') { P.rows.push({ k: name, id: key.key_id, tags: key.tags || [] }); continue; }
    const tr = Array.isArray(key.translations) ? key.translations : [];
    const str = v => (v && typeof v === 'object') ? JSON.stringify(v) : (v == null ? '' : String(v));
    const en = tr.find(t => t.language_iso === 'en');
    const enTxt = en ? str(en.translation) : '';
    if (!enTxt) continue;
    const fnObj = key.filenames || {};
    const fn = Object.values(fnObj).filter(Boolean).filter((v, j, a) => a.indexOf(v) === j).join(' | ');
    const c = (key.comments || []).map(x => String(x.comment || '')).filter(Boolean).join(' | ').slice(0, 400);
    const sc = (key.screenshots || []).map(s => ({ id: s.screenshot_id, t: s.title || '', d: String(s.description || '').slice(0, 200), u: s.url || '' }));
    const row = { k: name, id: key.key_id, tags: key.tags || [], d: String(key.description || '').slice(0, 600), cl: Number(key.char_limit || 0), c, ctx: String(key.context || '').slice(0, 300), fn, sc, pl: !!key.is_plural, en: enTxt, t: {}, m: {}, x: {} };
    for (const t of tr) {
      const iso = t.language_iso;
      if (iso === 'en' || PSEUDO.has(iso)) continue;
      const txt = str(t.translation);
      row.x[iso] = t.translation_id;
      if (!txt) continue;
      row.t[iso] = txt;
      row.m[iso] = (t.modified_at || '') + '|' + (t.is_reviewed ? 1 : 0) + '|' + (t.is_unverified ? 1 : 0) + '|' + (t.modified_by_email || '');
    }
    P.rows.push(row);
  }
});
return [{ json: res }];
